PROGRAM = "\nimport numpy as np\nfrom collections import Counter\n\n\ndef _shape(g, c):\n    ys, xs = np.nonzero(g == c)\n    y0, y1 = int(ys.min()), int(ys.max())\n    x0, x1 = int(xs.min()), int(xs.max())\n    return g[y0:y1 + 1, x0:x1 + 1] == c\n\n\ndef _hidden_if_match(clue_mask, shape, s):\n    # Number of off-grid scaled cells if some placement of the s-scaled shape\n    # (any integer offset, possibly hanging off any edge) has an in-grid part\n    # exactly equal to clue_mask; otherwise None.\n    H, W = clue_mask.shape\n    big = np.kron(shape.astype(np.int8), np.ones((s, s), np.int8)).astype(bool)\n    h, w = big.shape\n    ys, xs = np.nonzero(clue_mask)\n    if len(ys) == 0:\n        return None\n    cy0, cy1 = int(ys.min()), int(ys.max())\n    cx0, cx1 = int(xs.min()), int(xs.max())\n    if cy1 - cy0 + 1 > h or cx1 - cx0 + 1 > w:\n        return None\n    total = int(big.sum())\n    for oy in range(cy1 - h + 1, cy0 + 1):\n        for ox in range(cx1 - w + 1, cx0 + 1):\n            ys0, xs0 = max(oy, 0), max(ox, 0)\n            ys1, xs1 = min(oy + h, H), min(ox + w, W)\n            if ys0 >= ys1 or xs0 >= xs1:\n                continue\n            m = np.zeros((H, W), bool)\n            m[ys0:ys1, xs0:xs1] = big[ys0 - oy:ys1 - oy, xs0 - ox:xs1 - ox]\n            if np.array_equal(m, clue_mask):\n                return total - len(ys)\n    return None\n\n\ndef _crop(g, cand, bg):\n    sh = _shape(g, cand)\n    out = np.full(sh.shape, bg, dtype=int)\n    out[sh] = cand\n    return out.tolist()\n\n\ndef solve(demonstrations, grid):\n    g = np.asarray(grid, dtype=int)\n    counts = Counter(g.ravel().tolist())\n    maximum = max(counts.values())\n    backgrounds = [c for c,n in counts.items() if n == maximum]\n    if len(backgrounds) != 1:\n        raise ValueError('Background is not uniquely determined')\n    bg = backgrounds[0]\n    colours = [c for c in counts if c != bg]\n    shapes = {c: _shape(g,c) for c in colours}\n    answers = set()\n    for clue in colours:\n        for source in colours:\n            if source != clue and _hidden_if_match(g == clue, shapes[source], 2) is not None:\n                answers.add(tuple(tuple(row) for row in _crop(g,source,bg)))\n    if len(answers) != 1:\n        raise ValueError('Scaled clue does not determine one output sprite')\n    return [list(row) for row in next(iter(answers))]\n"

def build_program(d4, palette):
    return PROGRAM
